const s = $input.first();
const source_id = s.json.id || '';
const source_name = s.json['Source Name'] || '';
const channel_id = s.json['YouTube Channel ID'] || '';
const yt_link = s.json['YouTube_Links'] || '';
if (!channel_id) {
  console.log('[2a] No Channel ID for: ' + source_name);
  return [{ json: { _skip: true, source_id, source_name } }];
}
const lowerLink = yt_link.toLowerCase();
let content_filter = 'all';
if (lowerLink.includes('/shorts')) content_filter = 'shorts_only';
else if (lowerLink.includes('/videos')) content_filter = 'videos_only';

// Anchored 'since last scan' window. publishedAfter = YouTube_Last_Scanned minus a
// 2-day safety buffer (a late run or slow indexing can't open a gap; node 6 dedups
// any small overlap). Each run captures everything published since the previous scan;
// node 11 then writes today as the new last-scanned, so next week starts from here.
// Fallback for a never-scanned source: 8 days (sensible first weekly window).
const BUFFER_DAYS = 2;
const FALLBACK_DAYS = 8;
const lastScanned = s.json['YouTube_Last_Scanned'];
let publishedAfter;
if (lastScanned) {
  const bufferedTs = new Date(lastScanned).getTime() - (BUFFER_DAYS * 24 * 60 * 60 * 1000);
  publishedAfter = new Date(bufferedTs).toISOString().split('T')[0] + 'T00:00:00Z';
} else {
  const fallbackTs = Date.now() - (FALLBACK_DAYS * 24 * 60 * 60 * 1000);
  publishedAfter = new Date(fallbackTs).toISOString().split('T')[0] + 'T00:00:00Z';
}

console.log('[2a] Processing: ' + source_name + ' | publishedAfter: ' + publishedAfter);
return [{ json: { source_id, source_name, channel_id, content_filter, publishedAfter, yt_link } }];

const sourceInput = $('2a. Prepare Source Input').first().json;
const source_id = sourceInput.source_id;
const source_name = sourceInput.source_name;
const content_filter = sourceInput.content_filter || 'all';

const raw = $input.first().json;
if (!raw || raw.error || (raw.statusCode && raw.statusCode >= 400)) {
  console.log('[4] YouTube Search error for: ' + source_name + ' | ' + JSON.stringify(raw?.error || raw?.statusCode));
  return [{ json: { _skip_videos: true, source_id, source_name } }];
}

const items = raw.items || [];
const allIds = [...new Set(items.filter(i => i.id && i.id.videoId).map(i => i.id.videoId))];

console.log('[4] ' + source_name + ': ' + allIds.length + ' new video IDs');
if (!allIds.length) return [{ json: { _skip_videos: true, source_id, source_name } }];

return allIds.map(video_id => ({ json: { video_id, source_id, source_name, content_filter } }));

const existingItems = $input.all();
const existingIds = new Set(existingItems.map(i => i.json['Video ID'] || '').filter(id => id !== ''));
const incomingItems = $('4. Extract Video IDs').all();

if (incomingItems.length === 1 && incomingItems[0].json._skip_videos) {
  const { source_id, source_name } = incomingItems[0].json;
  console.log('[6] No videos from API for: ' + source_name);
  return [{ json: { _skip: true, source_id, source_name } }];
}

const seenThisRun = new Set();
const newVideos = [];
let skippedDupe = 0;

for (const item of incomingItems) {
  if (item.json._skip_videos) continue;
  const vid = item.json.video_id;
  if (!vid || existingIds.has(vid) || seenThisRun.has(vid)) { skippedDupe++; continue; }
  seenThisRun.add(vid);
  newVideos.push(item);
}

const source_id = incomingItems[0]?.json?.source_id || '';
const source_name = incomingItems[0]?.json?.source_name || '';
console.log('[6] Dupes skipped: ' + skippedDupe + ' | New: ' + newVideos.length);

if (!newVideos.length) return [{ json: { _skip: true, source_id, source_name } }];
return newVideos;

const rawItems = $input.all();
const metadata = (rawItems[0]?.json?.items) || [];
const sourceInput = $('2a. Prepare Source Input').first().json;
const source_id = sourceInput.source_id || '';
const source_name = sourceInput.source_name || '';
const content_filter = sourceInput.content_filter || 'all';

// Gate 1 per AlfredAI Outlier & Relevance Scoring Framework: OS >= 2.0x
// Platform multiplier (Part 1.3): YouTube content adapted to short-form gets +0.5x
// added to the outlier score before gating. Whole channel feeds short-form, so this
// applies to all YouTube outliers here.
const OUTLIER_THRESHOLD = 2.0;
const YOUTUBE_SHORTFORM_BONUS = 0.5;
const currentYear = new Date().getFullYear();
const currentYearStart = currentYear + '-01-01';

function tierFor(score) {
  if (score > 5.0) return 'Tier 1: Mega-Viral';
  if (score >= 2.0) return 'Tier 2: Strong Outlier';
  return null;
}

const candidates = [];
for (const meta of metadata) {
  if (!meta || !meta.id) continue;
  const snippet = meta.snippet || {};
  const stats = meta.statistics || {};
  if (!snippet.publishedAt || snippet.publishedAt < currentYearStart) {
    console.log('[8c] Pre-' + currentYear + ': ' + (snippet.title || meta.id));
    continue;
  }
  const duration = (meta.contentDetails || {}).duration || 'PT0S';
  let seconds = 0;
  const m = duration.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (m) seconds = (parseInt(m[1]||0)*3600) + (parseInt(m[2]||0)*60) + parseInt(m[3]||0);
  const isShort = content_filter === 'shorts_only' ? true : content_filter === 'videos_only' ? false : seconds <= 60;
  const contentType = isShort ? 'Short' : 'Video';
  const url = isShort ? 'https://www.youtube.com/shorts/' + meta.id : 'https://www.youtube.com/watch?v=' + meta.id;
  candidates.push({
    video_id: meta.id, title: snippet.title || 'Untitled', url,
    channel_id: snippet.channelId || '', description: snippet.description || '',
    tags: Array.isArray(snippet.tags) ? snippet.tags.join(', ') : '',
    published_at: snippet.publishedAt || '',
    view_count: parseInt(stats.viewCount || 0), like_count: parseInt(stats.likeCount || 0),
    comment_count: parseInt(stats.commentCount || 0), duration: seconds,
    content_type: contentType, platform: 'YouTube', source_id, source_name
  });
}

if (!candidates.length) {
  console.log('[8c] No ' + currentYear + '+ videos');
  return [{ json: { _skip: true, source_id, source_name } }];
}

// Per-creator baseline median over last 30 videos (Framework Part 1.1).
// OS = views / channel median over last 30 videos. Combines Video Library history with this run.
function median(arr) {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 === 0 ? (s[mid - 1] + s[mid]) / 2 : s[mid];
}

const historyByChannel = {};
let _existingRecs = [];
try {
  _existingRecs = $('5. Get All Existing Video IDs').all();
} catch (e) {
  console.log('[8c] node 5 history unavailable, using current-run median');
}
for (const rec of _existingRecs) {
  const ch = (rec.json['Channel ID'] || '').trim();
  if (!ch) continue;
  const v = parseInt(rec.json['View Count']) || 0;
  const ts = rec.json['Published At'] || '';
  if (!historyByChannel[ch]) historyByChannel[ch] = [];
  historyByChannel[ch].push({ v, ts });
}

const currentByChannel = {};
for (const c of candidates) {
  const ch = c.channel_id;
  if (!currentByChannel[ch]) currentByChannel[ch] = [];
  currentByChannel[ch].push({ v: c.view_count, ts: c.published_at });
}

const baselineByChannel = {};
const allChannels = new Set([...Object.keys(historyByChannel), ...Object.keys(currentByChannel)]);
for (const ch of allChannels) {
  const combined = [...(historyByChannel[ch] || []), ...(currentByChannel[ch] || [])]
    .filter(x => x.v > 0)
    .sort((a, b) => String(b.ts).localeCompare(String(a.ts)))
    .slice(0, 30)
    .map(x => x.v);
  baselineByChannel[ch] = median(combined);
}

const results = [];
for (const c of candidates) {
  const baseline = baselineByChannel[c.channel_id] || 0;
  const rawScore = baseline > 0 ? parseFloat((c.view_count / baseline).toFixed(2)) : 0;
  // Platform multiplier: +0.5x for YouTube -> short-form (Part 1.3)
  const boostedScore = parseFloat((rawScore + YOUTUBE_SHORTFORM_BONUS).toFixed(2));
  const tier = tierFor(boostedScore);
  if (!tier) { console.log('[8c] Skip (' + boostedScore + 'x): ' + c.title.substring(0,40)); continue; }
  console.log('[8c] OUTLIER (' + boostedScore + 'x, raw ' + rawScore + '): ' + c.title.substring(0,40));
  results.push({ json: { ...c, outlier_score: boostedScore, raw_outlier_score: rawScore, baseline_median: baseline, outlier_tier: tier } });
}
console.log('[8c] Outliers: ' + results.length + '/' + candidates.length + ' (Gate 1: ' + OUTLIER_THRESHOLD + 'x, +' + YOUTUBE_SHORTFORM_BONUS + ' YT bonus)');
return results.length > 0 ? results : [{ json: { _skip: true, source_id, source_name } }];

const items = $input.all();
let source_id = '';
let source_name = '';
for (const item of items) {
  if (item.json.source_id) {
    source_id = item.json.source_id;
    source_name = item.json.source_name || '';
    break;
  }
}
if (!source_id) {
  try {
    const si = $('2a. Prepare Source Input').first().json;
    source_id = si.source_id || '';
    source_name = si.source_name || '';
  } catch(e) {}
}
if (!source_id) { console.log('[10] No source_id, skipping'); return []; }
const today = new Date().toISOString().split('T')[0];
console.log('[10] Updating last scanned: ' + source_name);
return [{ json: { source_id, source_name, last_scanned: today } }];
